import fs from 'fs';
import path from 'path';
import { describe, expect, it } from 'vitest';
import { listBundledPacks, packContentHash } from '../scripts/pack-hash.mjs';

const DAEMON_DIR = path.resolve(__dirname, '..');
const GAMES_DIR = path.join(DAEMON_DIR, 'assets', 'games');
const LOCK_PATH = path.join(DAEMON_DIR, 'game-packs.lock.json');

type PackLock = Record<string, { version: string; contentHash: string }>;

// Installed packs only update when the bundled or catalog version is higher, so any change to a bundled pack
// (driver.js included, generated by the pretest build:games) must come with a version bump.
describe('bundled game packs lock', () => {
  const lock = JSON.parse(fs.readFileSync(LOCK_PATH, 'utf-8')) as PackLock;
  const packs = listBundledPacks(GAMES_DIR) as { id: string; dir: string; version: string }[];

  it('locks every bundled pack', () => {
    expect(Object.keys(lock).sort()).toEqual(packs.map((pack) => pack.id).sort());
  });

  it.each(packs.map((pack) => [pack.id, pack] as const))('%s matches its locked version and content', (id, pack) => {
    const locked = lock[id];
    const contentHash = packContentHash(pack.dir);
    if (locked?.version === pack.version) {
      expect(
        contentHash,
        `"${id}" changed without a version bump: bump "version" in its hosty-game.json, then run npm --prefix daemon run lock:games`
      ).toBe(locked.contentHash);
    }
    expect(locked, `"${id}" lock is out of date: run npm --prefix daemon run lock:games`).toEqual({
      version: pack.version,
      contentHash
    });
  });
});
